import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.io.StringWriter;
import java.util.StringTokenizer;

public class Main {
    static BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    static PrintWriter writer = new PrintWriter(new java.io.BufferedWriter(new java.io.OutputStreamWriter(System.out)));
    static StringTokenizer tokenizer = null;

    static void printf(String f, Object... a) {
        writer.printf(f, a);
    }

    static String next() {
        try {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    static long nextLong() {
        return Long.parseLong(next());
    }

    static long n, m, mod;
    static int[][] matrix;

    static int[][] multiply(int[][] one, int[][] two) {
        int[][] res = new int[(int) m][];
        for (int i = 0; i < (int) m; i++) {
            res[i] = new int[(int) m];
        }
        for (int i = 0; i < (int) m; i++) {
            for (int j = 0; j < (int) m; j++) {
                for (int k = 0; k < (int) m; k++) {
                    res[i][j] += (int) ((long) one[i][k] * (long) two[k][j] % mod);
                    res[i][j] %= (int) mod;
                }
            }
        }
        return res;
    }

    static int[][] power(long exp, int[][] base) {

        if (exp == 1) {
            return base;
        }

        int[][] res = power(exp / 2, base);
        res = multiply(res, res);
        if ((exp & 1) == 1) {
            res = multiply(res, base);
        }
        return res;
    }

    public static void main(String[] args) {
        mod = 1000000007;
        n = nextLong();
        m = nextLong();
        if (n < m) {
            printf("1");
            writer.flush();
            return;
        }
        if (n == m) {
            printf("2");
            writer.flush();
            return;
        }
        matrix = new int[(int) m][];
        for (int i = 0; i < (int) m; i++) {
            matrix[i] = new int[(int) m];
        }
        matrix[0][0] = 1;
        matrix[0][(int) m - 1] = 1;
        for (int i = 1; i < (int) m; i++) {
            matrix[i][i - 1] = 1;
        }

        System.out.println(power(n, matrix)[0][0]);

        writer.flush();
    }
}
